using LittleLeo.Events;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CleromancyAction", menuName = "Data/Battle/Battle Actions/Orion/Cleromancy Action")]
public class CleromancyAction : ChooseDiceAction
{
	[Header("Event")]
	[SerializeField]
	private ListDiceInstanceEvent OnDiscardUsedDicesWithoutExhaust;

	[Header("Dice Pools")]
	[SerializeField]
	private PlayerDiceInventoryData dicePool;

	[SerializeField]
	private PlayerDiceInventoryData discard;

	[Header("Light Shield")]
	[SerializeField]
	private DefaultEffectAction lightShieldAction;

	[SerializeField]
	private int amountOfLightShieldPerDice = 1;

	public DefaultEffectAction LightShieldAction => lightShieldAction;

	public int AmountOfLightShieldPerDice => amountOfLightShieldPerDice;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (playerHand)
		{
			return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 1;
		}
		return ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 0;
	}

	public override void Cast(GameObject source)
	{
		bool flag = dicePool.GetDicesAmount() > 0 || discard.GetDicesAmount() > 0;
		if (flag && ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerImmobilized())
		{
			flag = false;
		}
		if (flag)
		{
			lightShieldAction.DefaultCast(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject, amountOfLightShieldPerDice * diceList.Count, source, effectFeedback: true, gainingEffectVFXAndSFX: true);
			ReferenceSingleton<DiceDrawingHandler>.Instance.DrawActionCast(diceList.Count);
			OnDiscardUsedDicesWithoutExhaust.Raise(diceList);
		}
		else
		{
			lightShieldAction.CastTargetAmount(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject, amountOfLightShieldPerDice * diceList.Count, source);
			OnDiscardUsedDicesWithoutExhaust.Raise(diceList);
		}
	}
}
